                      }}

                    >

                      <div className="group relative overflow-hidden transition-all duration-700 hover:shadow-4xl hover:shadow-primary-500/20 transform hover:scale-110 rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black p-8 text-center w-80 mx-auto">

                        {/* Animated Icon Container */}

                        <div className="relative w-20 h-20 mx-auto mb-6">

                          <div className="absolute inset-0 bg-gradient-to-br from-secondary-500 to-primary-500 rounded-[2rem] transform -rotate-6 group-hover:-rotate-12 transition-transform duration-700 z-0"></div>

                          <div className="absolute inset-0 bg-gradient-to-br from-secondary-400 to-primary-400 rounded-[2rem] flex items-center justify-center transform group-hover:scale-110 transition-transform duration-500 z-10 shadow-lg">

                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white drop-shadow-md" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>

                              <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />

                            </svg>

                          </div>

                          <div className="absolute inset-0 bg-gradient-to-br from-secondary-500 to-primary-500 rounded-[2rem] blur-xl opacity-50 group-hover:opacity-100 transition-opacity duration-700 z-0"></div>

                        </div>

                        

                        <h3 className={`text-2xl font-bold mb-3 transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                          Fast Delivery

                        </h3>

                        <p className={`text-base transition-all duration-300 group-hover:text-gray-700 dark:group-hover:text-gray-300 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>

                          Quick and reliable delivery to ensure product freshness

                        </p>

                        

                        <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>

                        <div className="absolute inset-0 bg-gradient-to-br from-secondary-500/10 via-primary-500/10 to-secondary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>

                      </div>

                    </div>



                    {/* Best Price Card */}

                    <div 

                      className={`absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-in-out ${

                        featureSlide === 2 

                          ? 'opacity-100 scale-100 z-20 translate-x-0' 

                          : featureSlide === 0 

                            ? 'opacity-0 scale-75 translate-x-full rotate-y-45 z-10'

                            : 'opacity-0 scale-50 -translate-x-full -rotate-y-45 z-0'

                      }`}

                      style={{ 

                        transformStyle: 'preserve-3d',

                        transform: featureSlide === 2 

                          ? 'translate(-50%, -50%) translateX(0)' 

                          : featureSlide === 0 

                            ? 'translate(-50%, -50%) translateX(200%) rotateY(45deg)' 

                            : 'translate(-50%, -50%) translateX(-200%) rotateY(-45deg)'

                      }}

                    >

                      <div className="group relative overflow-hidden transition-all duration-700 hover:shadow-4xl hover:shadow-primary-500/20 transform hover:scale-110 rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black p-8 text-center w-80 mx-auto">

                        {/* Animated Icon Container */}

                        <div className="relative w-20 h-20 mx-auto mb-6">

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-[2rem] transform rotate-3 group-hover:rotate-6 transition-transform duration-700"></div>

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-400 to-secondary-400 rounded-[2rem] flex items-center justify-center transform group-hover:scale-110 transition-transform duration-500">

                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">

                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />

                            </svg>

                          </div>

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-[2rem] blur-xl opacity-50 group-hover:opacity-100 transition-opacity duration-700"></div>

                        </div>

                        

                        <h3 className={`text-2xl font-bold mb-3 transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                          Best Price

                        </h3>

                        <p className={`text-base transition-all duration-300 group-hover:text-gray-700 dark:group-hover:text-gray-300 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>

                          Competitive prices for premium quality dairy products

                        </p>

                        

                        <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>

                        <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-secondary-500/10 to-primary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>

                      </div>

                    </div>

                  </div>

                </div>

              </div>

            </div>

          </div>



          {/* Navigation Dots */}

          <div className="flex justify-center space-x-2 mt-8">

            {[0, 1, 2].map((index) => (

              <button

                key={index}

                onClick={() => setFeatureSlide(index)}

                className={`w-3 h-3 rounded-full transition-all duration-300 ${

                  featureSlide === index 

                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 w-8' 

                    : 'bg-gray-300 dark:bg-gray-600 hover:bg-gray-400 dark:hover:bg-gray-500'

                }`}

              />

            ))}

          </div>

        </div>

      </section>



      {/* Toast Container */}

      {toasts.map(toast => (

        <Toast

          key={toast.id}

          message={toast.message}

          type={toast.type}

          duration={toast.duration}

          onClose={() => removeToast(toast.id)}

        />

      ))}

    </div>

  );

};



export default Home;
